import{_ as r,o as d,c as a,a5 as e}from"./chunks/framework.CnBNXlt7.js";const c=JSON.parse('{"title":"使用提示","description":"","frontmatter":{},"headers":[],"relativePath":"code/os/windows/tips.md","filePath":"code/os/windows/tips.md","lastUpdated":1762096435000}'),i={name:"code/os/windows/tips.md"};function o(l,t,s,n,h,p){return d(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to &quot;使用提示&quot;">​</a></h1><h2 id="善用-win-r" tabindex="-1">善用 Win + R <a class="header-anchor" href="#善用-win-r" aria-label="Permalink to &quot;善用 Win + R&quot;">​</a></h2><p>常用的 Win+R 运行命令列表，涵盖系统工具、配置和管理功能：</p><p>系统常用</p><table tabindex="0"><thead><tr><th>命令</th><th>功能</th></tr></thead><tbody><tr><td>cmd</td><td>命令提示符</td></tr><tr><td>powershell</td><td>PowerShell</td></tr><tr><td>control</td><td>控制面板</td></tr><tr><td>explorer</td><td>文件资源管理器</td></tr><tr><td>taskmgr</td><td>任务管理器</td></tr><tr><td>regedit</td><td>注册表编辑器</td></tr><tr><td>msconfig</td><td>系统配置（启动项管理）</td></tr><tr><td>dxdiag</td><td>DirectX 诊断工具</td></tr><tr><td>winver</td><td>查看Windows版本</td></tr></tbody></table><p>网络相关</p><table tabindex="0"><thead><tr><th>命令</th><th>功能</th></tr></thead><tbody><tr><td>ncpa.cpl</td><td>网络连接（网卡设置）</td></tr><tr><td>devmgmt.msc</td><td>设备管理器</td></tr><tr><td>services.msc</td><td>服务管理</td></tr><tr><td>eventvwr.msc</td><td>事件查看器</td></tr></tbody></table><p>程序和功能</p><table tabindex="0"><thead><tr><th>命令</th><th>功能</th></tr></thead><tbody><tr><td>appwiz.cpl</td><td>卸载程序（程序和功能）</td></tr><tr><td>optionalfeatures</td><td>启用/关闭Windows功能</td></tr><tr><td>sysdm.cpl</td><td>系统属性（高级设置）</td></tr></tbody></table><p>磁盘和清理</p><table tabindex="0"><thead><tr><th>命令</th><th>功能</th></tr></thead><tbody><tr><td>diskmgmt.msc</td><td>磁盘管理</td></tr><tr><td>cleanmgr</td><td>磁盘清理</td></tr><tr><td>dfrgui</td><td>优化驱动器（碎片整理）</td></tr></tbody></table><p>组策略和权限</p><table tabindex="0"><thead><tr><th>命令</th><th>功能</th></tr></thead><tbody><tr><td>gpedit.msc</td><td>组策略编辑器（专业版可用）</td></tr><tr><td>secpol.msc</td><td>本地安全策略</td></tr><tr><td>lusrmgr.msc</td><td>本地用户和组管理</td></tr></tbody></table><p>远程和连接</p><table tabindex="0"><thead><tr><th>命令</th><th>功能</th></tr></thead><tbody><tr><td>mstsc</td><td>远程桌面连接</td></tr><tr><td>rdpclip</td><td>修复远程桌面剪贴板</td></tr><tr><td>ssh</td><td>SSH客户端（需启用功能）</td></tr></tbody></table><p>实用工具</p><table tabindex="0"><thead><tr><th>命令</th><th>功能</th></tr></thead><tbody><tr><td>calc</td><td>计算器</td></tr><tr><td>notepad</td><td>记事本</td></tr><tr><td>mspaint</td><td>画图</td></tr><tr><td>charmap</td><td>字符映射表（特殊符号）</td></tr><tr><td>magnify</td><td>放大镜</td></tr></tbody></table><p>系统信息</p><table tabindex="0"><thead><tr><th>命令</th><th>功能</th></tr></thead><tbody><tr><td>msinfo32</td><td>系统信息（硬件/组件详情）</td></tr><tr><td>perfmon</td><td>性能监视器</td></tr><tr><td>resmon</td><td>资源监视器</td></tr></tbody></table><p>快捷操作</p><table tabindex="0"><thead><tr><th>命令</th><th>功能</th></tr></thead><tbody><tr><td>shell:startup</td><td>开机启动文件夹</td></tr><tr><td>shell:desktop</td><td>桌面路径</td></tr><tr><td>.\\</td><td>当前用户目录</td></tr><tr><td>%temp%</td><td>临时文件夹</td></tr></tbody></table><p><strong>提示</strong>：输入时不分大小写，按 Enter 直接运行。</p><h2 id="qa" tabindex="-1">QA <a class="header-anchor" href="#qa" aria-label="Permalink to &quot;QA&quot;">​</a></h2><h3 id="win-11-图片无法打开" tabindex="-1">win 11 图片无法打开 <a class="header-anchor" href="#win-11-图片无法打开" aria-label="Permalink to &quot;win 11 图片无法打开&quot;">​</a></h3><p>设置-应用-安装的应用搜索【照片】-重置-修复即可</p><h3 id="bat-脚本相关" tabindex="-1">bat 脚本相关 <a class="header-anchor" href="#bat-脚本相关" aria-label="Permalink to &quot;bat 脚本相关&quot;">​</a></h3><p>参看 <a href="./cmd">cmd</a></p><h3 id="开机自启动-如新版-outlook-开机自启" tabindex="-1">开机自启动，如新版 outlook 开机自启 <a class="header-anchor" href="#开机自启动-如新版-outlook-开机自启" aria-label="Permalink to &quot;开机自启动，如新版 outlook 开机自启&quot;">​</a></h3><p>打开文件资源管理器，在地址栏中键入 <code>shell:startup</code>，然后按 Enter。<br> 这将打开一个文件夹，当您登录 Windows 时，快捷方式会在其中打开。</p><p><a href="https://answers.microsoft.com/zh-hans/outlook_com/forum/all/%e5%a6%82%e4%bd%95%e5%85%b3%e9%97%adoutlook/4e5a854d-1d21-4435-8368-efbd150a070c" target="_blank" rel="noreferrer">参考链接</a></p><h3 id="命令行使用代理" tabindex="-1">命令行使用代理 <a class="header-anchor" href="#命令行使用代理" aria-label="Permalink to &quot;命令行使用代理&quot;">​</a></h3><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-UV6ke" id="tab-PY40Vrr" checked><label data-title="cmd" for="tab-PY40Vrr">cmd</label><input type="radio" name="group-UV6ke" id="tab-tWcfTi5"><label data-title="powershell" for="tab-tWcfTi5">powershell</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HTTPS_PROXY=127.0.0.1:7890</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$env:HTTPS_PROXY = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1:7890&quot;</span></span></code></pre></div></div></div><h2 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h2><p>Windows系统中的常用快捷键可以极大地提高用户的操作效率，以下是一些常用的快捷键及其功能介绍：</p><h3 id="单独按键" tabindex="-1">单独按键 <a class="header-anchor" href="#单独按键" aria-label="Permalink to &quot;单独按键&quot;">​</a></h3><ul><li><strong>Esc</strong>：退出键，常用于取消当前操作或退出全屏模式。</li><li><strong>Tab</strong>：跳格键，在文本编辑软件中增加四个空格，Windows中可用于切换屏幕上的焦点。</li><li><strong>Ctrl</strong>：控制键，与其他键组合使用，实现多种功能，如复制（Ctrl+C）、粘贴（Ctrl+V）等。</li><li><strong>Shift</strong>：上档键，用于输入大写字母或与其他键组合实现特殊功能，如Shift+Delete快速彻底删除文件。</li><li><strong>Alt</strong>：换档键，常用于激活菜单命令或与其他键组合使用。</li><li><strong>Windows</strong>：打开“开始”菜单或与其他键组合使用，如Windows+D显示桌面。</li><li><strong>Delete</strong>：删除键</li></ul><h3 id="windows键组合" tabindex="-1">Windows键组合 <a class="header-anchor" href="#windows键组合" aria-label="Permalink to &quot;Windows键组合&quot;">​</a></h3><ul><li><strong>Windows + D</strong>：显示或隐藏桌面，快速切换到桌面视图。</li><li><strong>Windows + E</strong>：打开文件资源管理器，快速访问文件和文件夹。</li><li><strong>Windows + L</strong>：锁定计算机，保护隐私和安全。</li><li><strong>Windows + R</strong>：打开运行对话框，输入命令执行特定操作。</li><li><strong>Windows + Tab</strong>：切换任务视图，以3D效果显示打开的窗口和任务。</li><li><strong>Windows + M</strong>：最小化所有打开的窗口。</li><li><strong>Windows + Shift + M</strong>：还原所有最小化的窗口。</li><li><strong>Windows + F</strong>：打开“查找”窗口，搜索文件或文件夹。</li><li><strong>Windows + T</strong>：切换到任务栏中的下一个程序。</li><li><strong>Windows + U</strong>：在某些版本中打开“轻松访问中心”或执行其他特定功能（注意：不同版本的Windows可能有所不同）。</li></ul><h3 id="ctrl键组合" tabindex="-1">Ctrl键组合 <a class="header-anchor" href="#ctrl键组合" aria-label="Permalink to &quot;Ctrl键组合&quot;">​</a></h3><ul><li><strong>Ctrl + C</strong>：复制选中的内容到剪贴板。</li><li><strong>Ctrl + X</strong>：剪切选中的内容到剪贴板。</li><li><strong>Ctrl + V</strong>：粘贴剪贴板中的内容到当前位置。</li><li><strong>Ctrl + Z</strong>：撤销上一步操作。</li><li><strong>Ctrl + Y</strong>：恢复上一步撤销的操作。</li><li><strong>Ctrl + A</strong>：全选当前页面或文件夹中的内容。</li><li><strong>Ctrl + S</strong>：保存当前文档或文件。</li><li><strong>Ctrl + N</strong>：新建文件或文档。</li><li><strong>Ctrl + O</strong>：打开文件或文档。</li><li><strong>Ctrl + F</strong>：查找页面或文档中的内容。</li></ul><h3 id="其他常用组合" tabindex="-1">其他常用组合 <a class="header-anchor" href="#其他常用组合" aria-label="Permalink to &quot;其他常用组合&quot;">​</a></h3><ul><li><strong>Alt + F4</strong>：关闭当前窗口或退出程序。</li><li><strong>Ctrl + Alt + Delete</strong>：打开安全选项（Windows 10及更高版本为任务管理器）。</li><li><strong>PrintScreen</strong>：截取当前屏幕并保存到剪贴板。</li><li><strong>Alt + PrintScreen</strong>：截取当前活动窗口并保存到剪贴板。</li><li><strong>F1</strong>：打开帮助文档或提示。</li><li><strong>F2</strong>：重命名选中的文件或文件夹。</li><li><strong>F5</strong>：刷新当前页面或文件夹视图。</li><li><strong>Shift + Delete</strong>：永久删除文件。</li></ul><p>请注意，以上快捷键可能因Windows版本的不同而有所差异。此外，一些软件可能会定义自己的快捷键，这些快捷键可能与系统快捷键冲突，用户可以根据需要调整或禁用它们。</p><h2 id="微软输入法" tabindex="-1">微软输入法 <a class="header-anchor" href="#微软输入法" aria-label="Permalink to &quot;微软输入法&quot;">​</a></h2><p>中文输入法</p><p><strong>U 模式</strong>输入，首先在设置中打开（默认是开启的。设置→时间和语言→区域和语言→中文→选项→微软拼音→选项→高级→U模式输入）。在中文输入法下，键入 uu 即可进入 U 模式。<br> uudw：单位<br> uuxh：序号<br> uuts：特殊<br> uubd：标点<br> uusx：数学<br> uujh：几何<br> uuzm：字母</p>',46)])])}const g=r(i,[["render",o]]);export{c as __pageData,g as default};
